using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed from
            // "Discriminator" to "$type". Revert to keep compatibility with
            // existing 500K documents and direct SQL queries that filter on
            // c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product");

            // EF Core 9 breaking change: id format changed from "EntityType|Key"
            // to just the key value. Restore the old format so existing documents
            // (e.g. "Product|123") remain readable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            entity.HasIndex(p => p.Sku);
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // EF Core 9 breaking change: synchronous I/O now throws by default.
        // Existing code uses .ToList(); opt back in until fully async.
        base.OnConfiguring(options);
    }
}

